CREATE TABLE IF NOT EXISTS atelier_mtm_orders (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), customer_name TEXT NOT NULL, phone TEXT NOT NULL, style TEXT NOT NULL, leather_type TEXT, colour_finish TEXT, lining TEXT, chest_inches NUMERIC, waist_inches NUMERIC, shoulders_inches NUMERIC, sleeve_inches NUMERIC, body_length_inches NUMERIC, height TEXT, fit_preference TEXT, notes TEXT, status TEXT NOT NULL DEFAULT 'new', consent_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());